mkdir -p /app/bin /app/out; cat > /app/bin/fees.py <<'EOF'
import sys, os, csv, json, re, configparser, io
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

WD = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun']


def cents(s):
    return int((Decimal(s.strip()) * 100).to_integral_value())


def pdate(s):
    return date.fromisoformat(s.strip())


def digits(p):
    d = re.sub(r'\D', '', p or '')
    return int(d) if d else 0


def read_text(path):
    with open(path, encoding='utf-8-sig', newline='') as f:
        return f.read()


def read_csv(path):
    return list(csv.DictReader(io.StringIO(read_text(path))))


def parse_offset(s):
    s = s.strip()
    sign = -1 if s[0] == '-' else 1
    s = s.lstrip('+-')
    h, m = s.split(':')
    return sign * (int(h) * 60 + int(m))


def main(inp, outp):
    cp = configparser.RawConfigParser()
    cp.optionxform = str
    cp.read_string(read_text(os.path.join(inp, 'policy.ini')))
    lib = cp.get('statement', 'library').strip()
    pstart = pdate(cp.get('statement', 'period_start'))
    pend = pdate(cp.get('statement', 'period_end'))
    base_off = parse_offset(cp.get('clock', 'offset'))
    changes = []
    if cp.has_option('clock', 'changes'):
        for part in cp.get('clock', 'changes').split(';'):
            part = part.strip()
            if not part:
                continue
            ts, off = part.split()
            t = datetime.strptime(ts, '%Y-%m-%dT%H:%MZ').replace(tzinfo=timezone.utc)
            changes.append((t, parse_offset(off)))
    changes.sort()
    items = {}
    cats = {}
    for sec in cp.sections():
        if sec.lower().startswith('item:'):
            g = lambda k: cp.get(sec, k).strip()
            items[sec[5:].strip().lower()] = dict(
                name=sec[5:].strip(), loan_days=int(g('loan_days')), renewals=int(g('renewals')),
                grace=int(g('grace_days')), daily=cents(g('daily')), cap=cents(g('loan_cap')))
        elif sec.lower().startswith('category:'):
            g = lambda k: cp.get(sec, k).strip()
            sc = g('statement_cap')
            ex = cp.get(sec, 'exempt').strip() if cp.has_option(sec, 'exempt') else ''
            cats[sec[9:].strip().lower()] = dict(
                name=sec[9:].strip(), cap=None if sc.lower() == 'none' else cents(sc),
                discount=int(g('discount')),
                exempt={x.strip().lower() for x in ex.split(',') if x.strip()})

    branches = []
    open_days = {}
    for r in read_csv(os.path.join(inp, 'branches.csv')):
        b = r['branch'].strip()
        branches.append(b)
        open_days[b.upper()] = {d.strip().lower()[:3] for d in r['open_days'].split()}
    cal = {}  # branch -> list of (first,last,status)
    for r in read_csv(os.path.join(inp, 'calendar.csv')):
        d = r['date'].strip()
        if '..' in d:
            a, b = d.split('..')
        else:
            a = b = d
        cal.setdefault(r['branch'].strip().upper(), []).append(
            (pdate(a), pdate(b), r['status'].strip().lower()))

    def status_in(key, d):
        for a, b, s in cal.get(key, []):
            if a <= d <= b:
                return s
        return None

    def is_open(br, d):
        br = br.upper()
        s = status_in(br, d)
        if s is None:
            s = status_in('*', d)
        if s is not None:
            return s == 'open'
        return WD[d.weekday()] in open_days.get(br, set())

    def next_open(br, d):
        n = 0
        while not is_open(br, d) and n < 5000:
            d += timedelta(days=1)
            n += 1
        return d

    pat = {}
    for r in read_csv(os.path.join(inp, 'patrons.csv')):
        pat.setdefault(digits(r['patron']), []).append(
            (pdate(r['since']), r['patron'].strip(), r['category'].strip()))
    for v in pat.values():
        v.sort(key=lambda x: x[0])

    def category(pn, d):
        res = None
        for since, _, c in pat[pn]:
            if since <= d:
                res = c
        if res is None:
            res = pat[pn][0][2]
        return cats[res.lower()]

    waivers = []
    for r in read_csv(os.path.join(inp, 'waivers.csv')):
        if r['status'].strip().lower() != 'active':
            continue
        v = r['value'].strip()
        waivers.append((digits(r['patron']), r['loan'].strip(), None if v.lower() == 'full' else cents(v)))

    # events
    def local_from_instant(s):
        s = s.strip()
        if s.endswith('Z') or s.endswith('z'):
            s = s[:-1] + '+00:00'
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        dt = dt.astimezone(timezone.utc)
        off = base_off
        for t, o in changes:
            if dt >= t:
                off = o
        return (dt + timedelta(minutes=off)).replace(tzinfo=None)

    events = {}
    exdir = os.path.join(inp, 'exports')
    for fn in sorted(os.listdir(exdir)):
        if not (fn.endswith('.csv') or fn.endswith('.jsonl')):
            continue
        path = os.path.join(exdir, fn)
        rows = []
        if fn.endswith('.csv'):
            for r in read_csv(path):
                r = {k: (v or '').strip() for k, v in r.items() if k}
                if r.get('time'):
                    r['_t'] = datetime.strptime(r['time'], '%Y-%m-%d %H:%M')
                rows.append(r)
        else:
            for line in read_text(path).splitlines():
                line = line.strip()
                if not line:
                    continue
                o = json.loads(line)
                r = {k: ('' if v is None else str(v).strip()) for k, v in o.items()}
                if r.get('at'):
                    r['_t'] = local_from_instant(r['at'])
                rows.append(r)
        for r in rows:
            if r.get('event') and r['event'] not in events:
                events[r['event']] = r

    cancelled = set()
    for e in events.values():
        if e.get('type', '').lower() == 'void':
            cancelled.add(e.get('target', ''))

    checkouts = {}
    others = {}
    for eid, e in events.items():
        t = e.get('type', '').lower()
        if eid in cancelled or t == 'void':
            continue
        if t == 'checkout':
            checkouts[e['loan']] = e
        elif t in ('renew', 'return'):
            others.setdefault(e['loan'], []).append((e['_t'], t, e))

    loans = []
    for lid, c in checkouts.items():
        cd = c['_t'].date()
        if cd > pend:
            continue
        it = items[c['item_type'].lower()]
        br = c['branch']
        due = next_open(br, cd + timedelta(days=it['loan_days']))
        nren = 0
        ret = None
        for t, ty, e in sorted(others.get(lid, []), key=lambda x: x[0]):
            d = t.date()
            if ty == 'renew':
                if d <= due and nren < it['renewals'] and d <= pend:
                    nren += 1
                    due = next_open(br, d + timedelta(days=it['loan_days']))
            else:
                ret = d - timedelta(days=1) if e.get('via', '').lower() == 'dropbox' else d
                break
        if ret is not None and ret < pstart:
            continue
        if ret is not None and ret > pend:
            ret = None
        end = ret if ret is not None else pend
        od = 0
        d = due + timedelta(days=1)
        while d <= end:
            if is_open(br, d):
                od += 1
            d += timedelta(days=1)
        if od < 1:
            continue
        pn = digits(c['patron'])
        charged = od if od > it['grace'] else 0
        cat = category(pn, cd)
        fee = charged * it['daily']
        if it['name'].lower() in cat['exempt']:
            fee = 0
        fee = min(fee, it['cap'])
        fee = (fee * (100 - cat['discount']) + 50) // 100
        loans.append(dict(pn=pn, loan=lid, item=c['item'], item_type=it['name'], branch=br,
                          checkout=cd, due=due, returned=ret, overdue_days=od,
                          charged_days=charged, assessed=fee))

    by = {}
    for l in loans:
        by.setdefault(l['pn'], []).append(l)
    statements = []
    for pn in sorted(by):
        ls = by[pn]
        for l in ls:
            ws = [w for w in waivers if w[0] == pn and w[1] in (l['loan'], '*')]
            if any(w[2] is None for w in ws):
                wv = l['assessed']
            else:
                wv = min(sum(w[2] for w in ws), l['assessed'])
            l['waived'] = wv
            l['net'] = l['assessed'] - wv
            l['capped'] = 0
        cat = category(pn, pend)
        if cat['cap'] is not None:
            excess = sum(l['net'] for l in ls) - cat['cap']
            if excess > 0:
                order = sorted(ls, key=lambda l: (l['due'], l['loan']), reverse=True)
                for l in order:
                    if excess <= 0:
                        break
                    g = min(excess, l['net'])
                    l['capped'] = g
                    excess -= g
        ls.sort(key=lambda l: (l['due'], l['loan']))
        out = []
        for l in ls:
            l['billed'] = l['net'] - l['capped']
            out.append({
                'loan': l['loan'], 'item': l['item'], 'item_type': l['item_type'],
                'branch': l['branch'], 'checkout': l['checkout'].isoformat(),
                'due': l['due'].isoformat(),
                'returned': l['returned'].isoformat() if l['returned'] else None,
                'overdue_days': l['overdue_days'], 'charged_days': l['charged_days'],
                'assessed': l['assessed'], 'waived': l['waived'], 'capped': l['capped'],
                'billed': l['billed']})
        st = {'patron': sorted(pat[pn], key=lambda x: x[0])[-1][1], 'category': cat['name'], 'loans': out}
        for k in ('assessed', 'waived', 'capped', 'billed'):
            st[k] = sum(l[k] for l in out)
        statements.append(st)

    summ = []
    for b in branches:
        ls = [l for l in loans if l['branch'].upper() == b.upper()]
        s = {'branch': b, 'loans': len(ls), 'charged_days': sum(l['charged_days'] for l in ls)}
        for k in ('assessed', 'waived', 'capped', 'billed'):
            s[k] = sum(l[k] for l in ls)
        summ.append(s)

    res = {'library': lib, 'period': {'start': pstart.isoformat(), 'end': pend.isoformat()},
           'statements': statements, 'branches': summ}
    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(res, f, indent=2, ensure_ascii=False)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
